const moveHighlightTags = `-- name: MoveHighlightTags :many
WITH moved AS (
  DELETE FROM highlight_tag AS d WHERE d.workspace_id = $1 AND d.tag_id = $2 RETURNING d.highlight_id
), ins AS (
  INSERT INTO highlight_tag (workspace_id, highlight_id, tag_id)
  SELECT $1, highlight_id, $3 FROM moved ON CONFLICT DO NOTHING
)
SELECT highlight_id FROM moved
`

type MoveHighlightTagsParams struct {
	WorkspaceID uuid.UUID
	TagID       uuid.UUID
	TagID_2     uuid.UUID
}

// Re-point highlights from one tag to another; a highlight already carrying
// the target keeps one row. Returns the highlights that were moved.
func (q *Queries) MoveHighlightTags(ctx context.Context, arg MoveHighlightTagsParams) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, moveHighlightTags, arg.WorkspaceID, arg.TagID, arg.TagID_2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []uuid.UUID
	for rows.Next() {
		var highlight_id uuid.UUID
		if err := rows.Scan(&highlight_id); err != nil {
			return nil, err
		}
		items = append(items, highlight_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

